void terminal_boundary(const std::string& path,const std::vector<std::string>& imports){
    PersistenceService store(path,imports);root(store,"terminal-root");
    const auto captured=store.admit_agent_worker(lease("terminal-root","terminal-generation")).get().spec;
    start(store,"terminal-root","unfinished");store.claim_agent_worker_model(claim(captured,"unfinished")).get();
    start(store,"terminal-root","reserved-only",false);
    start(store,"terminal-root","finished");store.finish_model_call("terminal-root","terminal-root","finished").get();
    auto wrong=captured;wrong.pid+=1;
    rejects<Conflict>([&]{store.terminate_agent_worker(wrong,RunState::failed,"worker_exit").get();});
    rejects<std::invalid_argument>([&]{store.terminate_agent_worker(captured,RunState::completed,"worker_exit").get();});
    rejects<std::invalid_argument>([&]{store.terminate_agent_worker(captured,RunState::cancelled,"provider_failure").get();});
    XlangSqlite sql(path,imports);
    const std::vector<std::string> queries{"SELECT * FROM runs ORDER BY id","SELECT * FROM agent_model_call_reservations ORDER BY root_run_id,attempt_id","SELECT * FROM information ORDER BY category,id","SELECT * FROM agent_execution_budgets ORDER BY root_run_id","SELECT * FROM events ORDER BY seq","SELECT * FROM messages ORDER BY seq"};
    std::vector<std::vector<std::vector<SqlValue>>> before;for(const auto& query:queries)before.push_back(sql.execute(query).rows);
    sql.execute("CREATE TRIGGER fixture_worker_terminal_abort BEFORE UPDATE ON information WHEN OLD.category='native-agent-worker-leases' AND json_extract(NEW.payload,'$.state')='retired' BEGIN SELECT RAISE(ABORT,'fixture_worker_terminal_abort'); END");
    bool observed=false;try{store.terminate_agent_worker(captured,RunState::failed,"worker_exit").get();}catch(const DatabaseError& error){observed=std::string(error.what()).find("fixture_worker_terminal_abort")!=std::string::npos;}
    require(observed,"Online termination must encounter its injected lease write fault");
    for(std::size_t i=0;i<queries.size();++i)require(sql.execute(queries[i]).rows==before[i],"Online termination failure must roll back every run, reservation, claim, budget, history and event write");
    sql.execute("DROP TRIGGER fixture_worker_terminal_abort");
    require(store.terminate_agent_worker(captured,RunState::failed,"worker_exit").get().state==RunState::failed,"Drained worker exit must terminalize its root");
    require(store.agent_worker_lease(captured.generation).get().state=="retired"&&store.agent_worker_model_claim("terminal-root","unfinished").get().state=="uncertain"&&store.root_budget("terminal-root").get().model_calls_reserved==3,"Termination must retire the generation and preserve charged uncertainty");
    const auto attempts=sql.execute("SELECT attempt_id,state FROM agent_model_call_reservations WHERE root_run_id='terminal-root' ORDER BY attempt_id").rows;
    require(attempts==std::vector<std::vector<SqlValue>>{{std::string("finished"),std::string("finished")},{std::string("reserved-only"),std::string("interrupted")},{std::string("unfinished"),std::string("interrupted")}},"Only unfinished model reservations may be interrupted");
    const auto count=store.events("terminal-root").get().size();rejects<Conflict>([&]{store.terminate_agent_worker(captured,RunState::failed,"worker_exit").get();});require(store.events("terminal-root").get().size()==count,"Rejected duplicate terminal observation must append nothing");
    rejects<Conflict>([&]{store.claim_agent_worker_model(claim(captured,"reserved-only")).get();});
    const std::string queued="terminal-queued";store.create_session(queued,"Queued cancellation").get();store.start_prompt_run(queued,queued,R"({"content":"Cancel before start"})",RootBudgetSpec{"native.direct-agent",1,"workspace:none",provider,0,0,8,600000}).get();
    const auto pending=store.admit_agent_worker({"terminal-queued-generation",queued,queued,"workspace:none",1,12345,"134000000000000000","synthetic-queued-image",provider}).get().spec;
    require(store.terminate_agent_worker(pending,RunState::cancelled,"cancelled").get().state==RunState::cancelled&&store.root_budget(queued).get().model_calls_reserved==0,"Queued cancellation must retire without starting or charging a model");
    store.close();std::cout<<"Atomic online worker terminal boundary: rollback, exact identity, queued cancellation, interrupted reservations and retained charges verified.\n";
}

